502	+import { Component, DestroyRef, inject, signal } from '@angular/core';
503	+import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
504	+import { Router } from '@angular/router';
505	+import { BuchungenService } from '../shared/api/buchungen.service';
506	+
507	+@Component({
508	+  selector: 'app-buchung-abrufen',
509	+  imports: [],
510	+  templateUrl: './buchung-abrufen.html',
511	+  styleUrl: './buchung-abrufen.scss',
512	+})
513	+export class BuchungAbrufen {
514	+  private readonly buchungenService = inject(BuchungenService);
515	+  private readonly router = inject(Router);
516	+  private readonly destroyRef = inject(DestroyRef);
517	+
518	+  readonly referenzEingabe = signal('');
519	+  readonly laedt = signal(false);
520	+  readonly fehler = signal<string | null>(null);
521	+
522	+  protected absenden(): void {
523	+    const referenz = this.referenzEingabe().trim();
524	+    if (!referenz || this.laedt()) return;
525	+
526	+    this.laedt.set(true);
527	+    this.fehler.set(null);
528	+
529	+    this.buchungenService
530	+      .buchungAbrufen(referenz)
531	+      .pipe(takeUntilDestroyed(this.destroyRef))
532	+      .subscribe({
533	+        next: () => {
534	+          this.laedt.set(false);
535	+          this.router.navigate(['/buchungen', referenz]);
536	+        },
537	+        error: () => {
538	+          this.laedt.set(false);
539	+          this.fehler.set('Keine Buchung mit dieser Referenz gefunden.');
540	+        },
541	+      });
542	+  }
543	+}
