746	+import { CurrencyPipe, DatePipe } from '@angular/common';
747	+import { Component, inject, signal } from '@angular/core';
748	+import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
749	+import { ActivatedRoute } from '@angular/router';
750	+import { EMPTY, catchError, map, switchMap } from 'rxjs';
751	+import { BuchungenService } from '../shared/api/buchungen.service';
752	+import { BuchungDetail } from '../shared/models/buchung-detail';
753	+import { BadgeStatus } from '../shared/ui/badge-status/badge-status';
754	+import { Buchungsreferenz } from '../shared/ui/buchungsreferenz/buchungsreferenz';
755	+import { spielstaettenOffset } from '../shared/utils/zeitzone';
756	+
757	+type Ladezustand = 'laedt' | 'geladen' | 'fehler';
758	+
759	+@Component({
760	+  selector: 'app-buchungsdetail',
761	+  imports: [CurrencyPipe, DatePipe, BadgeStatus, Buchungsreferenz],
