764	+})
765	+export class Buchungsdetail {
766	+  private readonly buchungenService = inject(BuchungenService);
767	+  private readonly route = inject(ActivatedRoute);
768	+
769	+  readonly ladezustand = signal<Ladezustand>('laedt');
770	+  readonly buchung = signal<BuchungDetail | null>(null);
771	+
772	+  protected readonly spielstaettenOffset = spielstaettenOffset;
773	+
774	+  constructor() {
775	+    this.route.paramMap
776	+      .pipe(
777	+        map((paramMap) => paramMap.get('referenz')!),
778	+        switchMap((referenz) => {
779	+          this.ladezustand.set('laedt');
780	+          return this.buchungenService.buchungAbrufen(referenz).pipe(
781	+            catchError(() => {
782	+              this.ladezustand.set('fehler');
783	+              return EMPTY;
784	+            }),
785	+          );
786	+        }),
787	+        takeUntilDestroyed(),
788	+      )
789	+      .subscribe((buchung) => {
790	+        this.buchung.set(buchung);
791	+        this.ladezustand.set('geladen');
792	+      });
793	+  }
794	+}
